import React, { useState, useEffect, useMemo } from 'react';
import './WeatherHomepage.css';
import { useNavigate } from 'react-router-dom';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';


// --- API CONFIGURATION ---
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const WeatherHomepage = ({ onNavigateToWeather }) => {
  const navigate = useNavigate();
  const [currentWeather, setCurrentWeather] = useState(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [historicalData, setHistoricalData] = useState([]);
  const [historicalLoading, setHistoricalLoading] = useState(false);
  const [historicalError, setHistoricalError] = useState(null);
  const [selectedDays, setSelectedDays] = useState(3);
  const [selectedMetric, setSelectedMetric] = useState('temperature');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Update time every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Fetch current weather data
  useEffect(() => {
    const fetchWeatherData = async () => {
      try {
        // Pointing to your Backend URL
        
        // Added '/weather' to the path
        // MATCHES BACKEND: /api/weather/current
        // MATCHES BACKEND: /api/weather/historical-data
        // Removed the query parameter completely
        const response = await fetch(`${API_BASE_URL}/api/weather/current`);
        if (response.ok) {
          const data = await response.json();
          setCurrentWeather(data);
        }
      } catch (error) {
        console.error('Error fetching weather data:', error);
      }
    };

    fetchWeatherData();
    const interval = setInterval(fetchWeatherData, 300000); // Refresh every 5 minutes
    return () => clearInterval(interval);
  }, []);
  
  const fetchHistoricalData = async (daysToFetch = selectedDays) => {
    setHistoricalLoading(true);
    setHistoricalError(null);

    try {
      const response = await fetch(`${API_BASE_URL}/api/weather/historical-data?days=${daysToFetch}&station_id=weather-v2`);
      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || 'Failed to fetch historical weather data');
      }

      setHistoricalData(result.data || []);
    } catch (error) {
      console.error('Error fetching historical weather data:', error);
      setHistoricalError(error.message || 'Failed to load historical data');
      setHistoricalData([]);
    } finally {
      setHistoricalLoading(false);
    }
  };

  useEffect(() => {
    fetchHistoricalData(selectedDays);
  }, [selectedDays]);

  const chartData = useMemo(() => {
    if (!historicalData || historicalData.length === 0) return [];
    const TARGET_POINTS = 30;
    const step = Math.max(1, Math.ceil(historicalData.length / TARGET_POINTS));
    return historicalData.filter((_, index) => index % step === 0);
  }, [historicalData]);

  const metricOptions = [
    { value: 'temperature', label: 'Temperature (°C)' },
    { value: 'humidity', label: 'Humidity (%)' },
    { value: 'rainfall1h', label: 'Rainfall 1h (mm)' },
    { value: 'rainfall24h', label: 'Rainfall 24h (mm)' }
  ];

  const handleAccessWeatherApp = () => {
    navigate('/weather-map');
  };

  const handleOpenRiverDashboard = () => {
    navigate('/river-forecast');
  };

  

  const handleDataRequest = () => {
    navigate('/weather-map', { state: { openTab: 'request' } });
  }
  //const handleOpenRiverDashboard = () => {
    // This will open your river forecast dashboard (running on port 8000) in a new tab.
   // window.open('http://localhost:8000', '_blank');
  //};
  
const handleOpenDemandForecasting = () => {
  navigate('/demand-forecasting');
};
  return (
    <div className="weather-homepage-container">
      {/* Government Header */}
      <header className="gov-header">
        <div className="header-top">
          <div className="header-top-content">
            <div className="gov-links">
              {/* <a href="https://www.india.gov.in" target="_blank" rel="noopener noreferrer">
                Govt.of India
              </a> */}
              <a href="https://moes.gov.in" target="_blank" rel="noopener noreferrer">
                Ministry of Earth Sciences
              </a>
            </div>
            <div className="header-time">
              {currentTime.toLocaleString('en-IN', {
                timeZone: 'Asia/Kolkata',
                dateStyle: 'medium',
                timeStyle: 'short'
              })}
            </div>
          </div>
        </div>

        <div className="header-main">
          <div className="header-container">
            <div className="logo-section">
              <div className="logo">
                <i className="fas fa-cloud-sun"></i>
              </div>
              <div className="title-section">
                <h1>Weather Monitoring System</h1>
                <p>Adi Shankara Institute of Engineering & Technology</p>
                <div className="subtitle">Kalady, Kerala - 683574</div>
              </div>
            </div>

            <div className="header-actions">
  <button 
    className="btn btn-primary"
    onClick={handleAccessWeatherApp}
  >
    <i className="fas fa-tachometer-alt"></i>
    Access Live Data
  </button>
  <button 
    className="btn btn-success"
    onClick={handleOpenRiverDashboard}
  >
    <i className="fas fa-water"></i>
    Periyar River Forecast
  </button>
  
  {/* --- NEWLY ADDED WATER DEMAND REDIRECT BUTTON --- */}
  <button 
    className="btn btn-info"
    style={{ backgroundColor: '#0284c7', color: '#ffffff', border: 'none' }}
    onClick={handleOpenDemandForecasting}
  >
    <i className="fas fa-chart-pie" style={{ marginRight: '8px' }}></i>
    Water Demand Forecast
  </button>

  <button 
    className="btn btn-secondary"
    onClick={handleDataRequest}
  >
    <i className="fas fa-download"></i>
    Request Historical Data
  </button>
</div>
          </div>
        </div>
      </header>

      {/* Navigation */}
      {/* Navigation */}
<nav className="nav-bar">
  <div className="nav-container">

    {/* Mobile Menu Button */}
    <div 
      className="mobile-menu-btn"
      onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
    >
      <i className={mobileMenuOpen ? "fas fa-times" : "fas fa-bars"}></i>
    </div>

    <ul className={`nav-menu ${mobileMenuOpen ? 'active' : ''}`}>
      <li className="nav-item">
        <a href="/" className="nav-link active">Home</a>
      </li>

      <li className="nav-item">
        <a href="#about" className="nav-link">About</a>
      </li>

      <li className="nav-item">
        <a href="#services" className="nav-link">Services</a>
      </li>

      <li className="nav-item">
        <a href="#contact" className="nav-link">Contact</a>
      </li>
